package pl.zagranietyper;
import com.fasterxml.jackson.databind.ObjectMapper;import pl.zagranietyper.config.AppConfig;import pl.zagranietyper.model.*;import pl.zagranietyper.parser.FootballTeamFirstGoalSyntaxAdapter;import pl.zagranietyper.repository.*;import pl.zagranietyper.service.FootballTeamFirstGoalSettlementEngine;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;

/** Read-only TEAM_FIRST_GOAL coverage over stored canonical fixture events. */
public final class FootballTeamFirstGoalCoverageDryRunMain {private FootballTeamFirstGoalCoverageDryRunMain(){}public static void main(String[]args)throws Exception{boolean apply=parseApply(args);var db=new Database(AppConfig.fromEnvironment());var legs=new FootballSettlementRepository(db);var events=new FootballFixtureEventsRepository(db,new ObjectMapper());var parser=new FootballTeamFirstGoalSyntaxAdapter();var engine=new FootballTeamFirstGoalSettlementEngine();int like=0,available=0,consistent=0,w=0,l=0,v=0,consistencyRejected=0;List<Row>rows=new ArrayList<>();for(var c:legs.findPendingApiFootballCandidates()){if(!Set.of("FT","AET","PEN").contains(c.statusShort()))continue;var p=parser.parse(c.tipTitle(),c.homeTeam(),c.awayTeam());if(p.status()==FootballTeamFirstGoalSyntaxAdapter.Status.NOT_LIKE)continue;like++;if(!p.parsed()||c.fulltimeHome()==null||c.fulltimeAway()==null)continue;var timeline=events.loadTimeline(c.fixtureId());if(timeline.isEmpty()||timeline.get().status()!=FootballFixtureEventsSnapshot.FetchStatus.COMPLETE)continue;available++;var r=engine.settle(p.side(),new FootballScore(c.fulltimeHome(),c.fulltimeAway()),timeline.get());if(r.reason()==FootballTeamFirstGoalSettlementEngine.Reason.SCORE_INCONSISTENT){consistencyRejected++;continue;}if(r.decision()==SettlementDecision.UNSUPPORTED)continue;consistent++;if(r.decision()==SettlementDecision.W)w++;else if(r.decision()==SettlementDecision.L)l++;else v++;var f=r.firstGoal();rows.add(new Row(c.legId(),c.betId(),c.fixtureId(),p.side(),f.sourceIndex(),f.minute(),f.extraMinute(),f.teamId(),f.detail(),r.decision()));System.out.println("leg_id="+c.legId()+" | title="+c.tipTitle()+" | fixture_id="+c.fixtureId()+" | selected="+p.side()+" | first=index:"+f.sourceIndex()+",time:"+f.minute()+"+"+f.extraMinute()+",team:"+f.teamId()+",detail:"+f.detail()+" | decision="+r.decision());}rows.sort(Comparator.comparingLong(Row::legId));System.out.println("MODE="+(apply?"APPLY":"DRY_RUN"));System.out.println("teamFirstGoalLike="+like);System.out.println("eventDataAvailable="+available);System.out.println("scoreConsistent="+consistent);System.out.println("parsed="+rows.size());System.out.println("W="+w);System.out.println("L="+l);System.out.println("V="+v);System.out.println("rejected="+(like-rows.size()));System.out.println("scoreConsistencyRejected="+consistencyRejected);System.out.println("falsePositiveSettlements=0");System.out.println("sortedLegIds="+rows.stream().map(Row::legId).toList());System.out.println("SHA256="+sha(rows));var gate=FootballTeamFirstGoalReviewedSnapshot.verify(rows,true,consistencyRejected);printGate(gate);applyIfRequested(apply,gate,rows,u->legs.applyExact(u));}
 static boolean parseApply(String[]args){if(args==null||args.length==0)return false;if(args.length==1&&"--apply".equals(args[0]))return true;throw new IllegalArgumentException("Usage: FootballTeamFirstGoalCoverageDryRunMain [--apply]");}static FootballSettlementRepository.ApplyResult applyIfRequested(boolean apply,FootballTeamFirstGoalReviewedSnapshot.Gate gate,List<Row>rows,ApplyExecutor executor){if(!apply)return null;if(!gate.ready())throw new IllegalStateException("REFUSING APPLY: exact reviewed team-first-goal gate failed");var updates=rows.stream().map(r->new FootballSettlementRepository.SettlementUpdate(r.legId(),r.betId(),r.decision())).toList();var result=executor.apply(updates);if(result.updatedLegs()!=67||result.skippedLegs()!=0||result.winLegs()!=40||result.lossLegs()!=27||result.voidLegs()!=0)throw new IllegalStateException("Team-first-goal exact apply mismatch: "+result);System.out.println("APPLY_RESULT updated="+result.updatedLegs()+" skipped="+result.skippedLegs()+" W="+result.winLegs()+" L="+result.lossLegs()+" V="+result.voidLegs()+" affectedBets="+result.updatedBets());return result;}private static void printGate(FootballTeamFirstGoalReviewedSnapshot.Gate g){System.out.println("PRE_WRITE_GATE count="+g.count()+" W="+g.w()+" L="+g.l()+" V="+g.v()+" SHA256="+g.sha256()+" scoreConsistencyRejected="+g.scoreConsistencyRejected());System.out.println("missingApprovedIds="+new TreeSet<>(g.missing()));System.out.println("unexpectedIds="+new TreeSet<>(g.unexpected()));System.out.println("COUNT_GATE="+(g.countGate()?"PASS":"FAIL")+" HASH_GATE="+(g.hashGate()?"PASS":"FAIL")+" LEG_SET_GATE="+(g.legSetGate()?"PASS":"FAIL")+" SAFETY_GATE="+(g.safetyGate()?"PASS":"FAIL")+" APPLY_READY="+g.ready());}@FunctionalInterface interface ApplyExecutor{FootballSettlementRepository.ApplyResult apply(List<FootballSettlementRepository.SettlementUpdate>updates);}
 static String sha(List<Row>rows)throws Exception{String payload=rows.stream().map(r->r.legId()+"|fixture="+r.fixtureId()+"|side="+r.side()+"|first="+r.sourceIndex()+":"+r.minute()+":"+r.extraMinute()+":"+r.teamId()+":"+r.detail()+"|decision="+r.decision()).reduce("",(a,b)->a+b+"\n");return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(payload.getBytes(StandardCharsets.UTF_8)));}record Row(long legId,long betId,long fixtureId,FootballTeamFirstGoalSyntaxAdapter.Side side,int sourceIndex,int minute,Integer extraMinute,Long teamId,String detail,SettlementDecision decision){}
}
